CREATE TABLE IF NOT EXISTS support_slot_offers (id TEXT PRIMARY KEY,channel TEXT NOT NULL CHECK(channel IN ('member','guest')),request_id TEXT NOT NULL,quote_id TEXT NOT NULL,starts_json TEXT NOT NULL,minutes INTEGER NOT NULL CHECK(minutes BETWEEN 15 AND 180),prep_minutes INTEGER NOT NULL CHECK(prep_minutes BETWEEN 0 AND 120),wrap_minutes INTEGER NOT NULL CHECK(wrap_minutes BETWEEN 0 AND 120),learner_label TEXT NOT NULL,terms TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(channel,quote_id));
